const APP_JS="(function hospitalityApp(){\n  'use strict';\n  const cfg=window.APP_CONFIG||{}, project=cfg.project||{}, company=project.company||{}, h=project.hospitality||{}, preview=!!cfg.previewMode;\n  const root=document.getElementById('hospitalityApp'); let section=document.body.dataset.section||cfg.initialSection||'today';\n  const store=(()=>{try{localStorage.setItem('__ec13','1');localStorage.removeItem('__ec13');return localStorage}catch(_){const m={};return{getItem:k=>m[k]||null,setItem:(k,v)=>m[k]=String(v)}}})();\n  const org=project.organizationId||'demo'; const key=k=>`easycome:${org}:v13:${k}`;\n  const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[c]));\n  const num=v=>Number(v||0); const money=v=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(num(v));\n  const iso=v=>String(v||'').slice(0,10); const today=()=>new Date().toISOString().slice(0,10); const addDays=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString()};\n  const fmt=v=>{const d=new Date(v);return isNaN(d)?'—':new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'short'}).format(d)};\n  const CORE=[['today','Autopilot','index.html','✦'],['practices','Pratiche','pratiche.html','▣'],['calendar','Calendario','calendario.html','▦'],['bookings','Prenotazioni','prenotazioni.html','◫'],['inbox','Inbox','inbox.html','⇩'],['guests','Ospiti','ospiti.html','◎'],['housekeeping','Pulizie','pulizie.html','⌂'],['payments','Incassi','incassi.html','€'],['documents','Documenti','documenti.html','▤'],['compliance','Adempimenti','adempimenti.html','✓'],['deadlines','Scadenze','scadenze.html','◷'],['reports','Report','report.html','↗'],['settings','Impostazioni','impostazioni.html','⚙']];\n  let data={},drawer=null,drawerTab='overview';\n  function toast(t){const x=document.createElement('div');x.className='ec-toast';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),1900)}\n  function load(k){try{return JSON.parse(store.getItem(key(k))||'[]')}catch(_){return[]}}\n  function save(k,v){store.setItem(key(k),JSON.stringify(v));data[k]=v}\n  function upsert(k,row){const a=load(k),i=a.findIndex(x=>x.id===row.id);if(i>=0)a[i]={...a[i],...row};else a.push(row);save(k,a)}\n  function activity(title,detail,practice_ref=''){const a=load('activity');a.unshift({id:'a'+Date.now()+Math.random(),time:new Date().toISOString(),title,detail,practice_ref});save('activity',a.slice(0,80))}\n  function seed(){\n    if(!store.getItem(key('resources'))){const n=Math.max(4,num(h.unitCount||6));save('resources',Array.from({length:n},(_,i)=>({id:'r'+(i+1),name:`Camera ${i+1}`,category:i%3===0?'Deluxe':'Standard',capacity:i%4===0?3:2,cleaning_status:i===2?'Da preparare':'Pronta',active:true})))}\n    const rooms=load('resources');\n    if(!store.getItem(key('bookings'))){const names=['Giulia Romano','Marco De Luca','Anna Klein','Sophie Martin','Luca Ferri','Elena Russo','Thomas Weber','Sara Conti'];const channels=['Diretta','Booking.com','Airbnb'];const arr=[];for(let i=0;i<Math.max(9,rooms.length*2);i++){const st=(i%5)-1+Math.floor(i/5)*4,nights=2+(i%3===0?1:0),total=(115+(i%3)*35)*nights,balance=i%4===0?Math.round(total*.5):0;arr.push({id:'b'+(i+1),booking_ref:'EC-'+(240+i),customer_name:names[i%names.length],start_at:addDays(st),end_at:addDays(st+nights),resource_name:rooms[i%rooms.length]?.name||'Camera 1',people:2+(i%4===0?1:0),status:'Confermata',channel:channels[i%3],total,balance_due:balance,arrival_time:['14:30','15:00','16:00','17:30'][i%4]})}save('bookings',arr)}\n    const bookings=load('bookings');\n    if(!store.getItem(key('practices')))save('practices',bookings.map((b,i)=>({id:'pr'+i,booking_id:b.id,booking_ref:b.booking_ref,guest:b.customer_name,room:b.resource_name,start_at:b.start_at,end_at:b.end_at,channel:b.channel,status:i===1?'Attenzione':i<4?'In lavorazione':'In ordine',portal_sent:i!==1,guest_data:i!==1&&i!==4,identity_verified:i>1,visual_verified:i>1,contract_signed:i>2,tax_status:i===0?'Da incassare':i<3?'Calcolata':'Riscossa',alloggiati_status:i<2?'Da preparare':i<5?'Inviato':'Programmato',istat_status:i<3?'In coda':'Pronto',balance_status:b.balance_due>0?'Aperto':'Saldato',housekeeping_status:i===2?'Da preparare':'Pronta',automation:i===1?'Bloccata':'Attiva'})));\n    if(!store.getItem(key('guest_documents')))save('guest_documents',bookings.slice(0,8).map((b,i)=>({id:'gd'+i,booking_ref:b.booking_ref,guest_name:b.customer_name,document_status:i===1?'Mancante':i===4?'Da verificare':'Verificato',citizenship:i%4===2?'Germania':i%4===3?'Francia':'Italia',privacy:i!==1,contract:i>2})));\n    if(!store.getItem(key('payments')))save('payments',bookings.filter((_,i)=>i%2===0).map((b,i)=>({id:'pay'+i,booking_ref:b.booking_ref,guest:b.customer_name,date:today(),amount:b.balance_due?b.total-b.balance_due:b.total,method:i%2?'Bonifico':'Carta',type:i%3?'Soggiorno':'Caparra',status:'Incassato'})));\n    if(!store.getItem(key('housekeeping')))save('housekeeping',rooms.map((r,i)=>({id:'hk'+i,room:r.name,date:today(),status:i===2?'Da preparare':i===1?'In corso':'Pronta',assignee:['Maria','Elena','Paola'][i%3],trigger:i===2?'Check-out EC-242':'Programmato'})));\n    if(!store.getItem(key('documents')))save('documents',[\n      {id:'d1',name:'Documento identità · Giulia Romano',type:'Documento ospite',practice_ref:'EC-240',origin:'Ospite',status:'Verificato',date:today()},\n      {id:'d2',name:'Contratto soggiorno · Giulia Romano',type:'Contratto',practice_ref:'EC-240',origin:'Easy Come',status:'Firmato OTP',date:today()},\n      {id:'d3',name:'Ricevuta Alloggiati · EC-242',type:'Ricevuta invio',practice_ref:'EC-242',origin:'Alloggiati Web',status:'Archiviata',date:today()},\n      {id:'d4',name:'Prospetto tassa soggiorno · EC-243',type:'Tassa soggiorno',practice_ref:'EC-243',origin:'Easy Come',status:'Pronto',date:today()},\n      {id:'d5',name:'Fattura lavanderia settembre',type:'Fattura fornitore',practice_ref:'',origin:'Email',status:'Estratta',date:today()}\n    ]);\n    if(!store.getItem(key('structure_docs')))save('structure_docs',[\n      {id:'sd1',name:'CIN',value:'IT065105B4DEMO001',status:'Presente',expiry:'',note:'Codice struttura'},\n      {id:'sd2',name:'Codice regionale',value:'REG-DEMO-221',status:'Presente',expiry:'',note:'Registro regionale'},\n      {id:'sd3',name:'SCIA / comunicazione attività',value:'Protocollo 2026/1842',status:'Archiviata',expiry:'',note:'Documento struttura'},\n      {id:'sd4',name:'Polizza RC',value:'POL-88421',status:'Valida',expiry:iso(addDays(86)),note:'Promemoria rinnovo automatico'}\n    ]);\n    if(!store.getItem(key('inbox')))save('inbox',[\n      {id:'i1',source:'Booking.com',title:'Nuova prenotazione · Anna Klein',detail:'2 ospiti · Camera 3 · 11–14 set',kind:'Prenotazione',status:'Acquisita'},\n      {id:'i2',source:'Ospite',title:'Passaporto · Marco De Luca',detail:'Documento ricevuto dal portale check-in',kind:'Documento',status:'Da associare'},\n      {id:'i3',source:'Email',title:'Fattura Lavanderia Blu · €186',detail:'PDF letto: fornitore, imponibile e scadenza riconosciuti',kind:'Fattura',status:'Da confermare'},\n      {id:'i4',source:'WhatsApp',title:'“Arriviamo verso le 22:30”',detail:'Richiesta riconosciuta e collegata a EC-243',kind:'Messaggio',status:'Suggerimento pronto'}\n    ]);\n    if(!store.getItem(key('deadlines')))save('deadlines',[\n      {id:'s1',when:'Oggi',title:'Alloggiati · 2 arrivi',detail:'Invio entro la finestra prevista',status:'Automatico',kind:'stay'},\n      {id:'s2',when:'10 set',title:'Flusso statistico',detail:'Dati presenze pronti per il portale configurato',status:'Pronto',kind:'month'},\n      {id:'s3',when:'15 set',title:'Imposta di soggiorno',detail:'Scadenza definita dal profilo del Comune',status:'Da verificare',kind:'month'},\n      {id:'s4',when:fmt(addDays(86)),title:'Rinnovo polizza RC',detail:'Documento struttura in scadenza',status:'Promemoria',kind:'structure'}\n    ]);\n    if(!store.getItem(key('activity')))save('activity',[\n      {id:'a1',time:new Date(Date.now()-7*60000).toISOString(),title:'Schedina preparata',detail:'EC-242 · dati ospiti validati',practice_ref:'EC-242'},\n      {id:'a2',time:new Date(Date.now()-18*60000).toISOString(),title:'Tassa di soggiorno calcolata',detail:'EC-243 · regole Comune applicate',practice_ref:'EC-243'},\n      {id:'a3',time:new Date(Date.now()-29*60000).toISOString(),title:'Pulizia creata automaticamente',detail:'Camera 3 · assegnata a Paola',practice_ref:'EC-242'},\n      {id:'a4',time:new Date(Date.now()-44*60000).toISOString(),title:'Link pre-check-in inviato',detail:'EC-244 · email ospite',practice_ref:'EC-244'},\n      {id:'a5',time:new Date(Date.now()-58*60000).toISOString(),title:'Fattura fornitore classificata',detail:'Lavanderia Blu · €186',practice_ref:''}\n    ]);\n  }\n  function hydrate(){['resources','bookings','practices','guest_documents','payments','housekeeping','documents','structure_docs','inbox','deadlines','activity'].forEach(k=>data[k]=load(k))}\n  function badge(status,text=status){const s=String(status||'').toLowerCase();const cls=/inviato|verificato|riscossa|saldato|pronta|attiva|presente|archiviata|firmato|incassato|acquisita|valida|automatico/.test(s)?'ok':/manc|blocc|errore|scadut/.test(s)?'bad':/coda|calcolata|pronto|programmat|suggerimento|reminder/.test(s)?'info':'warn';return `<span class=\"ec-badge ${cls}\">${esc(text)}</span>`}\n  function completion(p){const vals=[p.portal_sent,p.guest_data,p.identity_verified,p.visual_verified,p.contract_signed,/riscossa/i.test(p.tax_status),/inviato|programmat/i.test(p.alloggiati_status),/pronto|inviato/i.test(p.istat_status),/saldato/i.test(p.balance_status),/pronta/i.test(p.housekeeping_status)];return Math.round(vals.filter(Boolean).length/vals.length*100)}\n  function nav(){return `<aside class=\"ec-side\"><div class=\"ec-brand\"><span class=\"ec-logo\">EC</span><div><b>${esc(company.name||'La tua struttura')}</b><small>HOSPITALITY AUTOPILOT</small></div></div><div class=\"ec-nav-title\">LAVORO</div><nav class=\"ec-nav\">${CORE.map(([id,l,href,ic])=>`<a href=\"${href}\" data-nav=\"${id}\" class=\"${section===id?'active':''}\"><span class=\"ico\">${ic}</span><span>${l}</span></a>`).join('')}</nav><div class=\"ec-side-status\"><span>Autopilot operativo</span></div><div class=\"ec-side-foot\"><b>${esc(h.type||'B&B')}</b><br>${esc(h.city||'')} · ${data.resources.length} alloggi<br><small>Easy Come lavora per eccezioni.</small></div></aside>`}\n  function head(k,t,d,actions=''){return `<header class=\"ec-page-head\"><div><span class=\"ec-kicker\">${k}</span><h1>${t}</h1><p>${d}</p></div><div class=\"ec-head-actions\">${actions}</div></header>`}\n  function upcoming(){return data.bookings.filter(b=>iso(b.end_at)>=today()).sort((a,b)=>iso(a.start_at).localeCompare(iso(b.start_at)))}\n  function todayView(){const open=data.practices.filter(p=>/attenzione|blocc/i.test(p.status)||/blocc/i.test(p.automation));const done=data.activity.filter(a=>iso(a.time)===today()).length+22;const arrivals=data.bookings.filter(b=>iso(b.start_at)===today()).length;const due=data.bookings.reduce((s,b)=>s+num(b.balance_due),0);return `${head('AUTOPILOT',`Easy Come ha già lavorato ${done} volte per te.`,'Non devi aprire ogni sezione: qui arrivano soltanto le eccezioni che richiedono una decisione.',`<button class=\"ec-btn\" data-guest-portal>Vedi esperienza ospite</button><button class=\"ec-btn orange\" data-run-auto>▶ Esegui Autopilot</button>`)}<div class=\"ec-kpis\"><div class=\"ec-kpi\"><span>Azioni automatiche oggi</span><strong>${done}</strong><small>messaggi, controlli, pratiche, documenti</small></div><div class=\"ec-kpi\"><span>Serve te</span><strong>${open.length}</strong><small>eccezioni da sbloccare</small></div><div class=\"ec-kpi\"><span>Arrivi oggi</span><strong>${arrivals}</strong><small>pratiche già preparate</small></div><div class=\"ec-kpi\"><span>Da incassare</span><strong>${money(due)}</strong><small>Easy Come può richiedere il saldo</small></div></div><div class=\"ec-grid-two\"><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Serve una tua decisione</h2><p>Se questa lista è vuota, non hai niente da fare.</p></div>${badge(open.length?'Attenzione':'Tutto chiuso',open.length?open.length+' eccezioni':'Tutto chiuso')}</div><div class=\"ec-card-list\">${open.map(p=>{const missing=!p.guest_data?'L’ospite non ha completato i dati':!p.identity_verified?'Documento da verificare':!p.visual_verified&&iso(p.start_at)<=today()?'Verifica identità de visu richiesta':/aperto/i.test(p.balance_status)?'Saldo ancora aperto':'Controllo manuale richiesto';return `<div class=\"ec-task action\" data-open-practice=\"${p.id}\"><div><b>${esc(p.guest)} · ${esc(p.booking_ref)}</b><p>${missing}</p></div><button class=\"ec-btn small\">Risolvi</button></div>`}).join('')||'<div class=\"ec-empty\">Nessuna eccezione. Easy Come continua a lavorare.</div>'}</div></section><section class=\"ec-panel dark\"><div class=\"ec-panel-head\"><div><h2>Fatto da Easy Come</h2><p>Log verificabile delle attività automatiche.</p></div>${badge('Attiva','LIVE')}</div><div class=\"ec-auto-feed\">${data.activity.slice(0,6).map(a=>`<div class=\"ec-auto-item\"><span class=\"ec-auto-icon\">✓</span><div><b>${esc(a.title)}</b><span>${esc(a.detail)}</span></div><time>${new Date(a.time).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div></section></div><section class=\"ec-panel\" style=\"margin-top:14px\"><div class=\"ec-panel-head\"><div><h2>Prossime pratiche</h2><p>Una prenotazione non è una riga: è un fascicolo che Easy Come porta fino alla chiusura.</p></div><button class=\"ec-btn small\" data-nav-jump=\"practices\">Apri tutte</button></div><div class=\"ec-card-list\">${upcoming().slice(0,5).map(b=>{const p=data.practices.find(x=>x.booking_ref===b.booking_ref);return `<div class=\"ec-task success\" data-open-practice=\"${p?.id||''}\"><div><b>${esc(b.customer_name)} · ${esc(b.resource_name)}</b><p>${fmt(b.start_at)}–${fmt(b.end_at)} · ${esc(b.channel)} · pratica ${completion(p||{})}%</p></div>${badge(p?.status||'In lavorazione')}</div>`}).join('')}</div></section>`}\n  function practicesView(){return `${head('PRATICHE','Ogni soggiorno ha un fascicolo completo.','Dati, documenti, firme, incassi, adempimenti, pulizia e log sono legati alla stessa pratica.',`<button class=\"ec-btn primary\" data-new-booking>+ Nuova pratica</button>`)}<div class=\"ec-practice-grid\">${data.practices.map(p=>{const c=completion(p);return `<article class=\"ec-practice\" data-open-practice=\"${p.id}\"><div class=\"ec-practice-top\"><div><span class=\"ec-kicker\">${esc(p.booking_ref)}</span><h3>${esc(p.guest)}</h3><p>${fmt(p.start_at)}–${fmt(p.end_at)} · ${esc(p.room)} · ${esc(p.channel)}</p></div>${badge(p.status)}</div><div class=\"ec-progress\"><i style=\"width:${c}%\"></i></div><div class=\"ec-practice-foot\"><span>${c}% completata</span><span>${/blocc/i.test(p.automation)?'Richiede intervento':'Autopilot attivo'}</span></div></article>`}).join('')}</div>`}\n  function calendarView(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return d});let html=`<div class=\"ec-cal-grid\"><div class=\"ec-cal-cell ec-cal-head\">Camera</div>${days.map(d=>`<div class=\"ec-cal-cell ec-cal-head\">${d.toLocaleDateString('it-IT',{weekday:'short',day:'2-digit'})}</div>`).join('')}`;data.resources.forEach(r=>{html+=`<div class=\"ec-cal-cell ec-cal-room\">${esc(r.name)}</div>`;days.forEach(d=>{const ds=d.toISOString().slice(0,10),b=data.bookings.find(x=>x.resource_name===r.name&&iso(x.start_at)<=ds&&iso(x.end_at)>ds);html+=`<div class=\"ec-cal-cell\">${b?`<span class=\"ec-book-chip ${/diretta/i.test(b.channel)?'direct':'ota'}\" data-open-booking=\"${b.id}\">${esc(b.customer_name)}<br>${esc(b.channel)}</span>`:''}</div>`});});return `${head('CALENDARIO','Disponibilità senza doppio lavoro.','Il calendario è alimentato dalle prenotazioni importate o create; la pratica nasce insieme alla prenotazione.')}<div class=\"ec-calendar\">${html}</div></div>`}\n  function bookingRows(rows){return rows.map(b=>{const p=data.practices.find(x=>x.booking_ref===b.booking_ref);return `<tr data-open-practice=\"${p?.id||''}\"><td><b>${esc(b.booking_ref)}</b><div class=\"ec-sub\">${esc(b.channel)}</div></td><td><b>${esc(b.customer_name)}</b></td><td>${fmt(b.start_at)} – ${fmt(b.end_at)}</td><td>${esc(b.resource_name)}</td><td>${money(b.total)}</td><td>${badge(p?.status||'In lavorazione')}</td></tr>`}).join('')}\n  function bookingsView(){return `${head('PRENOTAZIONI','Le prenotazioni entrano. Il lavoro parte da solo.','Booking, Airbnb, sito, email o inserimento manuale alimentano lo stesso flusso operativo.',`<button class=\"ec-btn primary\" data-new-booking>+ Prenotazione diretta</button>`)}<div class=\"ec-table-wrap\"><div class=\"ec-tools\"><input class=\"ec-search\" data-search placeholder=\"Cerca ospite, pratica o camera\"></div><table class=\"ec-table\"><thead><tr><th>Pratica</th><th>Ospite</th><th>Soggiorno</th><th>Camera</th><th>Totale</th><th>Stato</th></tr></thead><tbody data-booking-body>${bookingRows(data.bookings)}</tbody></table></div>`}\n  function inboxView(){return `${head('INBOX','Butta tutto qui. Easy Come lo mette a posto.','Email, PDF, documenti ospite, messaggi e nuove prenotazioni vengono riconosciuti, classificati e collegati alla pratica giusta.',`<button class=\"ec-btn orange\" data-upload-doc>+ Carica documento</button>`)}<section class=\"ec-panel\"><div class=\"ec-doc-drop\"><b>Trascina PDF, foto o documenti</b><p>Easy Come legge il contenuto, propone tipo, importi, ospite/pratica e scadenze. Tu confermi solo se serve.</p><button class=\"ec-btn primary\" data-upload-doc>Scegli file</button></div><div class=\"ec-list\">${data.inbox.map(i=>`<div class=\"ec-row\"><time>${esc(i.source)}</time><div><b>${esc(i.title)}</b><small>${esc(i.detail)}</small></div>${badge(i.kind)}<button class=\"ec-btn small\" data-process-inbox=\"${i.id}\">${/acquisita|confermata/i.test(i.status)?'Fatto':'Acquisisci'}</button></div>`).join('')}</div></section>`}\n  function guestsView(){return `${head('OSPITI','Il check-in lo compila l’ospite.','Easy Come raccoglie i dati, organizza i documenti e segnala solo ciò che non torna.',`<button class=\"ec-btn\" data-guest-portal>Apri portale ospite</button>`)}<div class=\"ec-table-wrap\"><table class=\"ec-table\"><thead><tr><th>Ospite</th><th>Pratica</th><th>Nazionalità</th><th>Documento</th><th>Privacy</th><th>Contratto</th></tr></thead><tbody>${data.guest_documents.map(g=>`<tr><td><b>${esc(g.guest_name)}</b></td><td>${esc(g.booking_ref)}</td><td>${esc(g.citizenship)}</td><td>${badge(g.document_status)}</td><td>${badge(g.privacy?'Accettata':'Mancante')}</td><td>${badge(g.contract?'Firmato OTP':'Da firmare')}</td></tr>`).join('')}</tbody></table></div>`}\n  function housekeepingView(){return `${head('PULIZIE','La pulizia nasce dal check-out.','Easy Come crea l’attività, la assegna e ti avvisa soltanto se la camera non è pronta prima del prossimo arrivo.')}<section class=\"ec-panel\"><div class=\"ec-list\">${data.housekeeping.map(x=>`<div class=\"ec-row\"><time>${esc(x.assignee)}</time><div><b>${esc(x.room)}</b><small>${esc(x.trigger)}</small></div>${badge(x.status)}<button class=\"ec-btn small\" data-clean=\"${x.id}\">${/pronta/i.test(x.status)?'Riapri':'Segna pronta'}</button></div>`).join('')}</div></section>`}\n  function paymentsView(){const inc=data.payments.reduce((s,p)=>s+num(p.amount),0),due=data.bookings.reduce((s,b)=>s+num(b.balance_due),0);return `${head('INCASSI','Easy Come sa cosa manca prima che tu lo chieda.','Caparre, saldi e tassa di soggiorno restano collegati alla pratica; i link di pagamento possono partire automaticamente.')}<div class=\"ec-kpis\"><div class=\"ec-kpi\"><span>Incassato</span><strong>${money(inc)}</strong><small>movimenti registrati</small></div><div class=\"ec-kpi\"><span>Saldi aperti</span><strong>${money(due)}</strong><small>da richiedere</small></div><div class=\"ec-kpi\"><span>Pratiche saldate</span><strong>${data.practices.filter(p=>/saldato/i.test(p.balance_status)).length}</strong><small>su ${data.practices.length}</small></div><div class=\"ec-kpi\"><span>Riconciliazione</span><strong>96%</strong><small>demo</small></div></div><div class=\"ec-table-wrap\"><table class=\"ec-table\"><thead><tr><th>Ospite</th><th>Pratica</th><th>Data</th><th>Tipo</th><th>Importo</th><th>Stato</th></tr></thead><tbody>${data.payments.map(p=>`<tr><td><b>${esc(p.guest)}</b></td><td>${esc(p.booking_ref)}</td><td>${fmt(p.date)}</td><td>${esc(p.type)}</td><td>${money(p.amount)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div>`}\n  function documentsView(){return `${head('DOCUMENTI','Un archivio che si costruisce da solo.','Documenti ospite, contratti, ricevute degli invii, prospetti e fatture vengono classificati e collegati alla pratica.',`<button class=\"ec-btn orange\" data-upload-doc>+ Documento</button>`)}<div class=\"ec-grid-two\"><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Archivio operativo</h2><p>Ricevuti, generati o scaricati dai portali.</p></div>${badge('Archiviata',data.documents.length+' file')}</div><div class=\"ec-card-list\">${data.documents.map(d=>`<div class=\"ec-task\"><div><b>${esc(d.name)}</b><p>${esc(d.type)} · ${esc(d.origin)}${d.practice_ref?' · '+esc(d.practice_ref):''}</p></div>${badge(d.status)}</div>`).join('')}</div></section><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Documenti struttura</h2><p>Un solo posto per codici, protocolli e rinnovi.</p></div></div><div class=\"ec-card-list\">${data.structure_docs.map(d=>`<div class=\"ec-task\"><div><b>${esc(d.name)}</b><p>${esc(d.value)}${d.expiry?' · scade '+fmt(d.expiry):''}</p></div>${badge(d.status)}</div>`).join('')}</div></section></div>`}\n  function complianceView(){const all=data.practices.filter(p=>/inviato|programmat/i.test(p.alloggiati_status)).length,istat=data.practices.filter(p=>/pronto|inviato/i.test(p.istat_status)).length,tax=data.practices.filter(p=>/riscossa/i.test(p.tax_status)).length;const score=Math.round((all+istat+tax)/(data.practices.length*3)*100);return `${head('ADEMPIMENTI','La burocrazia diventa un flusso, non una lista.','Il profilo normativo della struttura decide cosa serve per ogni soggiorno. Easy Come prepara, invia dove l’integrazione lo consente e conserva le evidenze.')}<div class=\"ec-compliance-hero\"><div><span class=\"ec-kicker\">COMPLIANCE ENGINE</span><h2>Una pratica entra una volta. I dati non si ricopiano più.</h2><p>Alloggiati, flusso statistico e imposta di soggiorno usano gli stessi dati raccolti dal portale ospite. Le regole cambiano per territorio: Easy Come usa il profilo configurato per Regione e Comune.</p></div><div class=\"ec-score\"><div><span>PRATICHE ALLINEATE</span><strong>${score}%</strong></div>${badge(score>75?'Attiva':'Attenzione',score>75?'In ordine':'Da verificare')}</div></div><div class=\"ec-grid-two\"><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Connettori</h2><p>Stato degli adempimenti automatici.</p></div></div><div class=\"ec-connector\"><span class=\"icon\">PS</span><div><b>Alloggiati Web</b><small>Preparazione schedine, invio via servizio web e archivio ricevute.</small></div>${badge('Attiva','Connesso')}</div><div class=\"ec-connector\"><span class=\"icon\">IS</span><div><b>Statistica regionale</b><small>Tracciato e invio secondo il portale configurato per la struttura.</small></div>${badge('Pronto','Configurato')}</div><div class=\"ec-connector\"><span class=\"icon\">€</span><div><b>Imposta di soggiorno</b><small>Regole Comune, esenzioni, incasso e integrazione portale quando disponibile.</small></div>${badge('Attiva','Regole attive')}</div><div class=\"ec-connector\"><span class=\"icon\">ID</span><div><b>CIN / dati struttura</b><small>Archivio anagrafica e controlli di presenza nei flussi configurati.</small></div>${badge('Presente','Presente')}</div></section><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Stato pratiche</h2><p>Quello che Easy Come deve ancora chiudere.</p></div></div><div class=\"ec-card-list\">${data.practices.slice(0,6).map(p=>`<div class=\"ec-task\" data-open-practice=\"${p.id}\"><div><b>${esc(p.booking_ref)} · ${esc(p.guest)}</b><p>Alloggiati: ${esc(p.alloggiati_status)} · ISTAT: ${esc(p.istat_status)} · Tassa: ${esc(p.tax_status)}</p></div>${badge(p.status)}</div>`).join('')}</div></section></div>`}\n  function deadlinesView(){return `${head('SCADENZE','Easy Come tiene la memoria al posto tuo.','Scadenze della singola pratica e della struttura confluiscono nello stesso calendario, con regole territoriali configurabili.')}<div class=\"ec-grid-two\"><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Prossime scadenze</h2><p>Generate da soggiorni, adempimenti e documenti.</p></div></div><div class=\"ec-timeline\">${data.deadlines.map(s=>`<div class=\"ec-timeline-item\"><i class=\"${/verificare|promemoria/i.test(s.status)?'warn':''}\">${/automatico|pronto/i.test(s.status)?'✓':'!'}</i><div><b>${esc(s.title)}</b><small>${esc(s.detail)}</small></div><time>${esc(s.when)}</time></div>`).join('')}</div></section><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Regole struttura</h2><p>Easy Come non usa scadenze generiche: le configura sulla tua attività.</p></div></div><div class=\"ec-card-list\"><div class=\"ec-task\"><div><b>Comune e tassa di soggiorno</b><p>Tariffe, esenzioni, numero massimo di notti e calendario dichiarazioni.</p></div>${badge('Attiva','Configurato')}</div><div class=\"ec-task\"><div><b>Regione / statistica</b><p>Portale e tracciato del movimento clienti.</p></div>${badge('Attiva','Configurato')}</div><div class=\"ec-task\"><div><b>Documenti struttura</b><p>Rinnovi e scadenze aggiunte dal titolare o lette dai documenti.</p></div>${badge('Pronto','Monitorati')}</div></div></section></div>`}\n  function reportsView(){const bookings=data.bookings,rooms=Math.max(1,data.resources.length),occ=Math.min(96,Math.round(bookings.filter(b=>iso(b.start_at)>=today()).length/(rooms*3)*100)),adr=Math.round(bookings.reduce((s,b)=>s+num(b.total),0)/Math.max(1,bookings.length)/2.5),hours=Math.round((data.activity.length+20)*4/6)/10;const months=['Apr','Mag','Giu','Lug','Ago','Set'];return `${head('REPORT','Non solo ricavi: misura il lavoro che hai eliminato.','Performance della struttura e valore operativo dell’automazione nello stesso posto.')}<div class=\"ec-kpis\"><div class=\"ec-kpi\"><span>Occupazione</span><strong>${occ}%</strong><small>periodo demo</small></div><div class=\"ec-kpi\"><span>ADR</span><strong>${money(adr)}</strong><small>prezzo medio</small></div><div class=\"ec-kpi\"><span>Tempo risparmiato</span><strong>${hours}h</strong><small>stima questa settimana</small></div><div class=\"ec-kpi\"><span>Pratiche senza intervento</span><strong>${Math.round(data.practices.filter(p=>!/blocc/i.test(p.automation)).length/data.practices.length*100)}%</strong><small>autopilot</small></div></div><div class=\"ec-grid-two\"><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Ricavi</h2><p>Andamento ultimi mesi.</p></div></div><div class=\"ec-chart\">${months.map((m,i)=>`<div class=\"ec-bar-col\"><div class=\"ec-bar ${i===5?'orange':''}\" style=\"height:${35+i*8+(i%2)*10}%\"></div><span>${m}</span></div>`).join('')}</div></section><section class=\"ec-panel\"><div class=\"ec-panel-head\"><div><h2>Autopilot</h2><p>Cosa ha assorbito Easy Come.</p></div></div><div class=\"ec-metric-list\"><div class=\"ec-metric\"><span>Check-in / dati ospite</span><strong>18 azioni</strong></div><div class=\"ec-metric\"><span>Adempimenti</span><strong>14 azioni</strong></div><div class=\"ec-metric\"><span>Messaggi e richieste saldo</span><strong>21 azioni</strong></div><div class=\"ec-metric\"><span>Documenti / classificazioni</span><strong>9 azioni</strong></div><div class=\"ec-metric\"><span>Pulizie generate</span><strong>7 attività</strong></div></div></section></div>`}\n  function settingsView(){return `${head('IMPOSTAZIONI','Configura una volta. Poi Easy Come esegue.','Regole della struttura, territorio, canali, pagamenti e livello di autonomia.')}<div class=\"ec-settings\"><section class=\"ec-panel\"><h2>Profilo operativo</h2><div class=\"ec-field\"><label>Tipo struttura</label><input value=\"${esc(h.type||'B&B')}\"></div><div class=\"ec-field\"><label>Comune</label><input value=\"${esc(h.city||'Palinuro')}\"></div><div class=\"ec-field\"><label>Numero alloggi</label><input value=\"${data.resources.length}\"></div><div class=\"ec-field\"><label>Portale statistico</label><select><option>Configurato durante onboarding</option></select></div></section><section class=\"ec-panel\"><h2>Autonomia Autopilot</h2><div class=\"ec-field\"><label>Messaggi pre-arrivo</label><select><option>Invia automaticamente</option></select></div><div class=\"ec-field\"><label>Alloggiati Web</label><select><option>Invia quando i dati sono validi</option></select></div><div class=\"ec-field\"><label>Richieste di pagamento</label><select><option>Invia con regole configurate</option></select></div><div class=\"ec-field\"><label>Eccezioni</label><select><option>Chiedi approvazione al titolare</option></select></div></section><section class=\"ec-panel\"><h2>Canali dati</h2><div class=\"ec-connector\"><span class=\"icon\">B</span><div><b>Booking.com</b><small>Prenotazioni e aggiornamenti</small></div>${badge('Attiva','Collegato')}</div><div class=\"ec-connector\"><span class=\"icon\">A</span><div><b>Airbnb</b><small>Prenotazioni e messaggi</small></div>${badge('Attiva','Collegato')}</div><div class=\"ec-connector\"><span class=\"icon\">@</span><div><b>Email dedicata</b><small>Allegati e richieste operative</small></div>${badge('Pronto','Attiva')}</div></section><section class=\"ec-panel\"><h2>Sicurezza & log</h2><div class=\"ec-task\"><div><b>Ogni automazione lascia una traccia</b><p>Chi/cosa ha modificato la pratica, quando e con quale esito.</p></div>${badge('Attiva','Audit')}</div><div class=\"ec-task\" style=\"margin-top:9px\"><div><b>Dati sensibili separati</b><p>Documenti ospite e credenziali dei portali vanno gestiti con storage e segreti protetti.</p></div>${badge('Pronto','Policy')}</div></section></div>`}\n  function view(){return section==='practices'?practicesView():section==='calendar'?calendarView():section==='bookings'?bookingsView():section==='inbox'?inboxView():section==='guests'?guestsView():section==='housekeeping'?housekeepingView():section==='payments'?paymentsView():section==='documents'?documentsView():section==='compliance'?complianceView():section==='deadlines'?deadlinesView():section==='reports'?reportsView():section==='settings'?settingsView():todayView()}\n  function render(){root.innerHTML=`<div class=\"ec-shell\">${nav()}<main class=\"ec-main\">${view()}</main></div><div id=\"ecDrawer\"></div><div id=\"ecOverlay\"></div>${preview?'<div class=\"ec-preview-note\">DEMO AUTOPILOT · DATI SIMULATI</div>':''}`;bind()}\n  function navigate(next){section=next;drawer=null;const main=root.querySelector('.ec-main'),drawerHost=document.getElementById('ecDrawer');if(drawerHost)drawerHost.innerHTML='';if(!main){render();return}main.innerHTML=view();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===section));bind()}\n  function practiceById(id){return data.practices.find(x=>x.id===id)}\n  function openPractice(id){drawer=id;drawerTab='overview';renderDrawer()}\n  function renderDrawer(){const p=practiceById(drawer),host=document.getElementById('ecDrawer');if(!p||!host)return;const b=data.bookings.find(x=>x.booking_ref===p.booking_ref),doc=data.guest_documents.find(x=>x.booking_ref===p.booking_ref),files=data.documents.filter(x=>x.practice_ref===p.booking_ref),pays=data.payments.filter(x=>x.booking_ref===p.booking_ref);const tabs=[['overview','Pratica'],['guest','Ospite'],['docs','Documenti'],['compliance','Adempimenti'],['money','Incassi'],['log','Log']];let body='';if(drawerTab==='guest')body=`<div class=\"ec-drawer-grid\"><div><span>Dati ospite</span><b>${p.guest_data?'Completi':'Da completare'}</b></div><div><span>Documento</span><b>${esc(doc?.document_status||'Mancante')}</b></div><div><span>Privacy</span><b>${doc?.privacy?'Accettata':'Da acquisire'}</b></div><div><span>Contratto</span><b>${doc?.contract?'Firmato OTP':'Da firmare'}</b></div></div><div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:12px\"><button class=\"ec-btn primary\" data-guest-portal>Apri portale ospite</button>${p.visual_verified?badge('Verificato','Identità de visu verificata'):`<button class=\"ec-btn green\" data-visual-check>✓ Conferma verifica de visu</button>`}</div>`;else if(drawerTab==='docs')body=`${files.map(d=>`<div class=\"ec-task\"><div><b>${esc(d.name)}</b><p>${esc(d.type)} · ${esc(d.origin)}</p></div>${badge(d.status)}</div>`).join('')||'<div class=\"ec-empty\">Nessun documento ancora.</div>'}<button class=\"ec-btn\" style=\"margin-top:12px\" data-upload-doc>+ Aggiungi documento</button>`;else if(drawerTab==='compliance')body=`<div class=\"ec-drawer-grid\"><div><span>Alloggiati</span><b>${esc(p.alloggiati_status)}</b></div><div><span>Statistica</span><b>${esc(p.istat_status)}</b></div><div><span>Tassa soggiorno</span><b>${esc(p.tax_status)}</b></div><div><span>Autopilot</span><b>${esc(p.automation)}</b></div></div><div class=\"ec-card-list\" style=\"padding:14px 0\"><div class=\"ec-task\"><div><b>Regola applicata</b><p>I dati vengono riutilizzati dal fascicolo; se manca qualcosa l’invio si blocca e compare come eccezione.</p></div>${badge('Attiva','Guardrail')}</div></div>`;else if(drawerTab==='money')body=`<div class=\"ec-drawer-grid\"><div><span>Totale soggiorno</span><b>${money(b?.total)}</b></div><div><span>Saldo</span><b>${money(b?.balance_due)}</b></div><div><span>Stato</span><b>${esc(p.balance_status)}</b></div><div><span>Tassa soggiorno</span><b>${esc(p.tax_status)}</b></div></div>${pays.map(x=>`<div class=\"ec-task\" style=\"margin-top:9px\"><div><b>${money(x.amount)}</b><p>${esc(x.type)} · ${esc(x.method)}</p></div>${badge(x.status)}</div>`).join('')}`;else if(drawerTab==='log')body=`<div class=\"ec-timeline\">${data.activity.filter(a=>!a.practice_ref||a.practice_ref===p.booking_ref).slice(0,10).map(a=>`<div class=\"ec-timeline-item\"><i>✓</i><div><b>${esc(a.title)}</b><small>${esc(a.detail)}</small></div><time>${new Date(a.time).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div>`;else body=`<div class=\"ec-drawer-grid\"><div><span>Camera</span><b>${esc(p.room)}</b></div><div><span>Canale</span><b>${esc(p.channel)}</b></div><div><span>Soggiorno</span><b>${fmt(p.start_at)} – ${fmt(p.end_at)}</b></div><div><span>Completamento</span><b>${completion(p)}%</b></div><div><span>Stato pratica</span><b>${esc(p.status)}</b></div><div><span>Autopilot</span><b>${esc(p.automation)}</b></div></div><div class=\"ec-progress\"><i style=\"width:${completion(p)}%\"></i></div><div class=\"ec-card-list\" style=\"padding:8px 0\"><div class=\"ec-task\"><div><b>Check-in ospite</b><p>${p.portal_sent?'Link inviato':'Link da inviare'} · ${p.guest_data?'dati completi':'dati mancanti'}</p></div>${badge(p.guest_data?'Verificato':'Attenzione')}</div><div class=\"ec-task\"><div><b>Burocrazia</b><p>Alloggiati ${esc(p.alloggiati_status)} · statistica ${esc(p.istat_status)}</p></div>${badge(p.alloggiati_status)}</div><div class=\"ec-task\"><div><b>Incassi e tassa</b><p>Saldo ${esc(p.balance_status)} · tassa ${esc(p.tax_status)}</p></div>${badge(p.balance_status)}</div></div>`;host.innerHTML=`<div class=\"ec-drawer-bg\" data-close></div><aside class=\"ec-drawer\"><header><div><span>${esc(p.booking_ref)} · PRATICA SOGGIORNO</span><h2>${esc(p.guest)}</h2><p>${fmt(p.start_at)} – ${fmt(p.end_at)} · ${esc(p.room)}</p></div><button data-close>×</button></header><nav class=\"ec-drawer-tabs\">${tabs.map(([id,l])=>`<button data-tab=\"${id}\" class=\"${drawerTab===id?'active':''}\">${l}</button>`).join('')}</nav><div class=\"ec-drawer-body\">${body}</div><footer><button data-close>Chiudi</button><button data-send-portal>Invia check-in</button><button class=\"primary\" data-run-practice>Esegui pratica</button></footer></aside>`;host.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>{drawer=null;host.innerHTML=''});host.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{drawerTab=x.dataset.tab;renderDrawer()});host.querySelectorAll('[data-guest-portal]').forEach(x=>x.onclick=guestPortal);host.querySelectorAll('[data-upload-doc]').forEach(x=>x.onclick=uploadDemo);host.querySelectorAll('[data-visual-check]').forEach(x=>x.onclick=()=>{p.visual_verified=true;p.status='In lavorazione';p.automation='Attiva';upsert('practices',p);activity('Identità verificata de visu',`${p.booking_ref} · guardrail sbloccato`,p.booking_ref);hydrate();runPractice(p.id)});host.querySelector('[data-send-portal]').onclick=()=>{p.portal_sent=true;upsert('practices',p);activity('Link check-in inviato',`${p.booking_ref} · portale ospite`,p.booking_ref);hydrate();renderDrawer();toast('Link check-in inviato (demo)')};host.querySelector('[data-run-practice]').onclick=()=>runPractice(p.id)}\n  function runPractice(id){const p=practiceById(id);if(!p)return;if(!p.portal_sent){p.portal_sent=true;activity('Link check-in inviato',`${p.booking_ref} · automatico`,p.booking_ref)}if(p.guest_data){p.identity_verified=true;p.contract_signed=true;if(p.visual_verified){p.alloggiati_status='Inviato'}else if(iso(p.start_at)<=today()){p.alloggiati_status='In attesa verifica de visu';p.status='Attenzione';p.automation='Bloccata'}else{p.alloggiati_status='Programmato'};p.istat_status='Pronto';if(!/riscossa/i.test(p.tax_status))p.tax_status='Riscossa';activity('Adempimenti pratica eseguiti',`${p.booking_ref} · Alloggiati e flusso statistico preparati`,p.booking_ref)}else{p.status='Attenzione';p.automation='Bloccata';activity('Autopilot bloccato',`${p.booking_ref} · mancano dati ospite`,p.booking_ref)}if(/saldato/i.test(p.balance_status)&&p.guest_data&&p.visual_verified){p.status='In ordine';p.automation='Attiva'}upsert('practices',p);hydrate();render();if(drawer){drawer=id;renderDrawer()}toast(p.automation==='Bloccata'?(p.guest_data?'Serve la verifica identità de visu':'Serve completare i dati ospite'):'Pratica aggiornata da Autopilot')}\n  function runAutopilot(){data.practices.forEach(p=>{if(!p.portal_sent){p.portal_sent=true;activity('Link check-in inviato',`${p.booking_ref} · automatico`,p.booking_ref)}if(p.guest_data){p.identity_verified=true;p.contract_signed=true;if(p.visual_verified&&!/inviato/i.test(p.alloggiati_status)){p.alloggiati_status='Inviato';activity('Schedina inviata',`${p.booking_ref} · ricevuta archiviata (demo)`,p.booking_ref)}else if(!p.visual_verified&&iso(p.start_at)<=today()){p.alloggiati_status='In attesa verifica de visu';p.status='Attenzione';p.automation='Bloccata'}p.istat_status='Pronto';if(/calcolata/i.test(p.tax_status))p.tax_status='Riscossa';if(/saldato/i.test(p.balance_status)&&p.visual_verified){p.status='In ordine';p.automation='Attiva'}}else{p.status='Attenzione';p.automation='Bloccata'}upsert('practices',p)});hydrate();render();toast('Autopilot completato: restano solo le eccezioni')}\n  function guestPortal(){const host=document.getElementById('ecOverlay');const p=data.practices[1]||data.practices[0];host.innerHTML=`<div class=\"ec-modal-bg\"><section class=\"ec-modal\"><header><h2>Esperienza ospite · ${esc(p.guest)}</h2></header><div class=\"body ec-portal\"><div class=\"ec-portal-phone\"><div class=\"ec-portal-top\"><small>${esc(company.name||'La tua struttura')}</small><h2>Il tuo check-in</h2><p>${fmt(p.start_at)} – ${fmt(p.end_at)} · ${esc(p.room)}</p></div><div class=\"ec-portal-body\"><div class=\"ec-portal-step\"><i>✓</i><div><b>Dati personali</b><small>Nome, nascita, residenza e recapiti</small></div>${badge('Verificato','Completato')}</div><div class=\"ec-portal-step pending\"><i>2</i><div><b>Documento d’identità</b><small>Foto o scansione; Easy Come estrae i campi e segnala incoerenze</small></div>${badge('Attenzione','Da caricare')}</div><div class=\"ec-portal-step\"><i>✓</i><div><b>Privacy e regole</b><small>Accettazione e firma OTP quando prevista</small></div>${badge('Verificato','Completato')}</div><div class=\"ec-portal-step pending\"><i>3</i><div><b>Verifica identità de visu</b><small>In presenza o con modalità visiva in tempo reale configurata; Easy Come blocca gli invii se manca.</small></div>${badge('Attenzione','All’arrivo')}</div><div class=\"ec-portal-step\"><i>€</i><div><b>Saldo e tassa di soggiorno</b><small>Importi calcolati in base alla pratica e alle regole del Comune</small></div>${badge('Pronto','Pronto')}</div><div class=\"ec-portal-step\"><i>→</i><div><b>Arrivo</b><small>Orario, istruzioni, accesso e servizi extra</small></div>${badge('Pronto','Disponibile')}</div><button class=\"ec-btn orange\" style=\"width:100%;margin-top:16px\" data-complete-portal>Completa demo check-in</button></div></div></div><footer><button class=\"ec-btn\" data-close-modal>Chiudi</button></footer></section></div>`;host.querySelector('[data-close-modal]').onclick=()=>host.innerHTML='';host.querySelector('[data-complete-portal]').onclick=()=>{p.guest_data=true;p.identity_verified=true;p.contract_signed=true;p.portal_sent=true;p.automation='Attiva';p.status='In lavorazione';upsert('practices',p);const gd=data.guest_documents.find(x=>x.booking_ref===p.booking_ref);if(gd){gd.document_status='Verificato';gd.privacy=true;gd.contract=true;upsert('guest_documents',gd)}activity('Check-in online completato',`${p.booking_ref} · dati e documento validati`,p.booking_ref);hydrate();host.innerHTML='';render();toast('Check-in ospite completato (demo)')}}\n  function uploadDemo(){const host=document.getElementById('ecOverlay');host.innerHTML=`<div class=\"ec-modal-bg\"><section class=\"ec-modal\"><header><h2>Acquisisci un documento</h2></header><div class=\"body\"><div class=\"ec-doc-drop\"><b>Demo lettura documento</b><p>In produzione: upload PDF/foto → estrazione campi → classificazione → proposta pratica/scadenza.</p><button class=\"ec-btn primary\" data-simulate-upload>Simula fattura fornitore</button></div></div><footer><button class=\"ec-btn\" data-close-modal>Chiudi</button></footer></section></div>`;host.querySelector('[data-close-modal]').onclick=()=>host.innerHTML='';host.querySelector('[data-simulate-upload]').onclick=()=>{upsert('documents',{id:'d'+Date.now(),name:'Fattura Energia Service · settembre',type:'Fattura fornitore',practice_ref:'',origin:'Upload',status:'Estratta',date:today()});activity('Documento acquisito','Fattura Energia Service · importo e scadenza riconosciuti');hydrate();host.innerHTML='';render();toast('Documento classificato e archiviato')}}\n  function newBooking(){const host=document.getElementById('ecOverlay');host.innerHTML=`<div class=\"ec-modal-bg\"><section class=\"ec-modal\"><header><h2>Nuova prenotazione diretta</h2></header><form data-booking-form><div class=\"body\"><div class=\"ec-drawer-grid\"><div class=\"ec-field\"><label>Ospite</label><input name=\"guest\" required></div><div class=\"ec-field\"><label>Camera</label><select name=\"room\">${data.resources.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></div><div class=\"ec-field\"><label>Arrivo</label><input name=\"start\" type=\"date\" value=\"${today()}\" required></div><div class=\"ec-field\"><label>Partenza</label><input name=\"end\" type=\"date\" value=\"${iso(addDays(2))}\" required></div><div class=\"ec-field\"><label>Totale</label><input name=\"total\" type=\"number\" value=\"280\"></div><div class=\"ec-field\"><label>Canale</label><select name=\"channel\"><option>Diretta</option><option>Booking.com</option><option>Airbnb</option></select></div></div></div><footer><button type=\"button\" class=\"ec-btn\" data-close-modal>Annulla</button><button class=\"ec-btn primary\">Crea e avvia Autopilot</button></footer></form></section></div>`;host.querySelector('[data-close-modal]').onclick=()=>host.innerHTML='';host.querySelector('[data-booking-form]').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const ref='EC-'+Math.floor(500+Math.random()*400),id='b'+Date.now();upsert('bookings',{id,booking_ref:ref,customer_name:f.guest,start_at:new Date(f.start+'T15:00').toISOString(),end_at:new Date(f.end+'T10:00').toISOString(),resource_name:f.room,people:2,status:'Confermata',channel:f.channel,total:num(f.total),balance_due:num(f.total),arrival_time:'15:00'});upsert('practices',{id:'pr'+Date.now(),booking_id:id,booking_ref:ref,guest:f.guest,room:f.room,start_at:new Date(f.start+'T15:00').toISOString(),end_at:new Date(f.end+'T10:00').toISOString(),channel:f.channel,status:'In lavorazione',portal_sent:true,guest_data:false,identity_verified:false,visual_verified:false,contract_signed:false,tax_status:'Da calcolare',alloggiati_status:'In attesa dati',istat_status:'In attesa dati',balance_status:'Aperto',housekeeping_status:'Programmato',automation:'Attiva'});upsert('guest_documents',{id:'gd'+Date.now(),booking_ref:ref,guest_name:f.guest,document_status:'Mancante',citizenship:'—',privacy:false,contract:false});activity('Nuova pratica creata',`${ref} · link check-in preparato`,ref);hydrate();host.innerHTML='';navigate('practices');toast('Prenotazione creata: Autopilot avviato')}}\n  function bind(){document.querySelectorAll('[data-nav]').forEach(a=>{if(preview)a.onclick=e=>{e.preventDefault();navigate(a.dataset.nav)}});document.querySelectorAll('[data-nav-jump]').forEach(x=>x.onclick=()=>navigate(x.dataset.navJump));document.querySelectorAll('[data-open-practice]').forEach(x=>x.onclick=()=>x.dataset.openPractice&&openPractice(x.dataset.openPractice));document.querySelectorAll('[data-open-booking]').forEach(x=>x.onclick=()=>{const b=data.bookings.find(b=>b.id===x.dataset.openBooking),p=b&&data.practices.find(p=>p.booking_ref===b.booking_ref);if(p)openPractice(p.id)});document.querySelectorAll('[data-new-booking]').forEach(x=>x.onclick=newBooking);document.querySelectorAll('[data-run-auto]').forEach(x=>x.onclick=runAutopilot);document.querySelectorAll('[data-guest-portal]').forEach(x=>x.onclick=guestPortal);document.querySelectorAll('[data-upload-doc]').forEach(x=>x.onclick=uploadDemo);document.querySelectorAll('[data-clean]').forEach(x=>x.onclick=()=>{const row=data.housekeeping.find(v=>v.id===x.dataset.clean);row.status=/pronta/i.test(row.status)?'Da preparare':'Pronta';upsert('housekeeping',row);activity('Pulizia aggiornata',`${row.room} · ${row.status}`);hydrate();render();toast('Pulizia aggiornata')});document.querySelectorAll('[data-process-inbox]').forEach(x=>x.onclick=()=>{const row=data.inbox.find(v=>v.id===x.dataset.processInbox);row.status='Acquisita';upsert('inbox',row);activity('Inbox elaborata',row.title);hydrate();render();toast('Elemento acquisito e classificato')});document.querySelector('[data-search]')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase(),body=document.querySelector('[data-booking-body]');if(body){body.innerHTML=bookingRows(data.bookings.filter(b=>`${b.customer_name} ${b.booking_ref} ${b.resource_name}`.toLowerCase().includes(q)));document.querySelectorAll('[data-open-practice]').forEach(x=>x.onclick=()=>x.dataset.openPractice&&openPractice(x.dataset.openPractice))}})}\n  seed();hydrate();render();\n})();";

function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function on(p){return p?.templateId==='hospitality'||(p?.modules||[]).includes('hospitality_core')}
function page(section,p){const name=esc(p.company?.name||'La tua struttura');return '<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171713"><title>'+name+' · Easy Come Hospitality</title><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="assets/hospitality.css"></head><body data-section="'+section+'"><div id="hospitalityApp"></div><script src="js/config.js"></script><script>if(window.APP_CONFIG&&window.APP_CONFIG.dataMode===\'cloud\'){document.write(\'<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"><\\/script>\')}</script><script src="js/hospitality.js"></script><script>if(\'serviceWorker\' in navigator&&location.protocol!==\'file:\'){addEventListener(\'load\',()=>navigator.serviceWorker.register(\'sw.js\').catch(()=>{}))}</script></body></html>'}
function redirect(file){return '<!doctype html><meta charset="utf-8"><script>location.replace("'+file+'")</script><p><a href="'+file+'">Apri Easy Come Hospitality</a></p>'}
function files(project){if(!on(project))return[];const pages=[];const map=[['today','index.html'],['practices','pratiche.html'],['calendar','calendario.html'],['bookings','prenotazioni.html'],['inbox','inbox.html'],['guests','ospiti.html'],['housekeeping','pulizie.html'],['payments','incassi.html'],['documents','documenti.html'],['compliance','adempimenti.html'],['deadlines','scadenze.html'],['reports','report.html'],['settings','impostazioni.html']];map.forEach(([s,f])=>pages.push({name:f,data:page(s,project)}));const manifest=JSON.stringify({name:(project.company?.name||'Struttura')+' · Easy Come',short_name:'Easy Come',start_url:'./index.html',display:'standalone',background_color:'#f2eee6',theme_color:'#171713',icons:[{src:'assets/favicon.svg',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]},null,2);const assets=['./','./index.html','./pratiche.html','./calendario.html','./prenotazioni.html','./inbox.html','./ospiti.html','./pulizie.html','./incassi.html','./documenti.html','./adempimenti.html','./scadenze.html','./report.html','./impostazioni.html','./assets/hospitality.css','./js/config.js','./js/hospitality.js'];const sw='const CACHE="easycome-hospitality-v13-autopilot";const ASSETS='+JSON.stringify(assets)+';self.addEventListener("install",e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));self.addEventListener("activate",e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)))})';return [...pages,{name:'frontdesk.html',data:redirect('index.html')},{name:'gestionale.html',data:redirect('index.html')},{name:'performance.html',data:redirect('report.html')},{name:'intelligence.html',data:redirect('report.html')},{name:'easycome-hub.html',data:redirect('index.html')},{name:'manifest.webmanifest',data:manifest},{name:'sw.js',data:sw},{name:'assets/hospitality.css',data:APP_CSS},{name:'js/hospitality.js',data:APP_JS}]}


export const ECHospitalityTemplates={files};
